package cn.flower.mall;

import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.mock.web.MockMultipartFile;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.junit.jupiter.api.Assertions.*;
import static cn.flower.mall.Store.m;
import static cn.flower.mall.MallService.id;
import java.util.*;
import java.util.concurrent.*;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import javax.imageio.ImageIO;

@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:tests;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1","app.seed-demo=false","app.bootstrap-admin-password=Admin123!","app.jwt-secret=test-key-minimum-32-characters-for-jwt-tests","app.upload-dir=./target/test-uploads"})
@AutoConfigureMockMvc
class BusinessFlowTest {
 @org.springframework.test.context.DynamicPropertySource static void database(org.springframework.test.context.DynamicPropertyRegistry r){r.add("spring.datasource.url",()->System.getProperty("test.db.url","jdbc:h2:mem:tests;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1"));r.add("spring.datasource.username",()->System.getProperty("test.db.user","sa"));r.add("spring.datasource.password",()->System.getProperty("test.db.password",""));}
 @Autowired MallService s; @Autowired Store db; @Autowired Tokens tokens; @Autowired MockMvc http; @Autowired MediaService media; @Autowired GreetingService ai;
 long u,v,p,a,admin;
 @BeforeEach void setup(){String suffix=UUID.randomUUID().toString().replace("-","").substring(0,12);u=id(s.register(m("username","u"+suffix,"password","Pass123!","nickname","甲")).get("id"));v=id(s.register(m("username","v"+suffix,"password","Pass123!","nickname","乙")).get("id"));admin=id(db.one("SELECT id FROM account WHERE role='ADMIN'",m()).get("id"));long cat=db.add("category",m("name",suffix));p=db.add("product",m("category_id",cat,"name","测试花束","price","99.90","description","测试","specification","19枝","cover","/images/bouquet-1.svg","stock",5));s.saveAddress(u,m("receiver","甲","phone","13800000000","province","浙江","city","杭州","district","西湖","detail","测试地址","is_default",1));a=id(((List<Map<String,Object>>)s.addresses(u)).get(0).get("id"));}
 Map<String,Object> create(long uid,long address,long pid,int qty,String key){return (Map<String,Object>)s.createOrder(uid,m("request_key",key,"address_id",address,"items",List.of(m("product_id",pid,"quantity",qty)),"greeting","愿你喜乐"));}
 Map<String,Object> create(){return create(u,a,p,1,UUID.randomUUID().toString());}
 int stock(){return ((Number)db.one("SELECT stock FROM product WHERE id=#{p.id}",m("id",p)).get("stock")).intValue();}
 String bearer(long uid){return "Bearer "+tokens.create(db.one("SELECT * FROM account WHERE id=#{p.id}",m("id",uid)));}
 @Test void serverPriceAndSnapshotsAreAuthoritative(){var o=create();assertEquals("99.90",o.get("total").toString());db.update("product",p,m("name","改名","price","1.00"));var item=((List<Map<String,Object>>)s.order(id(o.get("id")),u).get("items")).get(0);assertEquals("测试花束",item.get("name"));assertEquals("99.90",item.get("price").toString());assertTrue(o.get("address_snapshot").toString().contains("测试地址"));}
 @Test void submissionAndPaymentAreIdempotent(){var o=create(u,a,p,1,"same");var duplicate=create(u,a,p,1,"same");assertEquals(o.get("id"),duplicate.get("id"));assertEquals(4,stock());long oid=id(o.get("id"));s.pay(u,oid,true);s.pay(u,oid,true);assertEquals(1,id(db.one("SELECT COUNT(*) AS n FROM payment_record WHERE order_id=#{p.id}",m("id",oid)).get("n")));}
 @Test void failedPaymentAndCancelRestoreOnce(){var o=create();long oid=id(o.get("id"));s.pay(u,oid,false);assertEquals(0,id(s.order(oid,u).get("status")));s.cancel(u,oid);assertEquals(5,stock());assertThrows(BusinessException.class,()->s.cancel(u,oid));assertEquals(5,stock());assertThrows(BusinessException.class,()->s.pay(u,oid,true));}
 @Test void transactionRollsBackAllStockOnFailure(){long missing=db.add("product",m("category_id",db.one("SELECT category_id FROM product WHERE id=#{p.id}",m("id",p)).get("category_id"),"name","缺货","price","9.00","specification","1枝","cover","/images/bouquet-1.svg","stock",0));assertThrows(BusinessException.class,()->s.createOrder(u,m("request_key","rollback","address_id",a,"items",List.of(m("product_id",p,"quantity",1),m("product_id",missing,"quantity",1)))));assertEquals(5,stock());}
 @Test void concurrentBuyersCannotOversell()throws Exception {db.update("product",p,m("stock",1));s.saveAddress(v,m("receiver","乙","phone","13900000000","province","浙江","city","杭州","district","西湖","detail","另一地址","is_default",1));long va=id(((List<Map<String,Object>>)s.addresses(v)).get(0).get("id"));var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{List<Future<Boolean>> tasks=new ArrayList<>();for(long who:new long[]{u,v})tasks.add(pool.submit(()->{start.await();try{create(who,who==u?a:va,p,1,UUID.randomUUID().toString());return true;}catch(BusinessException e){return false;}}));start.countDown();int successes=0;for(var task:tasks)if(task.get(10,TimeUnit.SECONDS))successes++;assertEquals(1,successes);assertEquals(0,stock());}finally{pool.shutdownNow();}}
 @Test void refundsBoundedAndNoDoubleRestore(){long oid=id(create().get("id"));s.pay(u,oid,true);assertThrows(BusinessException.class,()->s.applyRefund(u,m("order_id",oid,"amount","100.00","reason","不需要")));long rid=id(((Map<?,?>)s.applyRefund(u,m("order_id",oid,"amount","30.00","reason","部分退款"))).get("id"));assertThrows(BusinessException.class,()->s.applyRefund(u,m("order_id",oid,"amount","1.00","reason","重复")));s.auditRefund(admin,rid,true,m());s.processRefund(rid,false);s.processRefund(rid,false);assertEquals("30.00",s.order(oid,u).get("refunded").toString());assertEquals(4,stock());long rest=id(((Map<?,?>)s.applyRefund(u,m("order_id",oid,"amount","69.90","reason","剩余退款"))).get("id"));s.auditRefund(admin,rest,true,m());s.processRefund(rest,false);assertEquals(5,stock());assertEquals(6,id(s.order(oid,u).get("status")));}
 @Test void refundFailureCanRetryAndRejectNeedsReason(){long oid=id(create().get("id"));s.pay(u,oid,true);long rid=id(((Map<?,?>)s.applyRefund(u,m("order_id",oid,"amount","99.90","reason","错误"))).get("id"));assertThrows(BusinessException.class,()->s.auditRefund(admin,rid,false,m()));s.auditRefund(admin,rid,true,m());s.processRefund(rid,true);assertEquals(5,id(((Map<?,?>)s.refund(rid,u)).get("refund_status")));assertEquals("0.00",s.order(oid,u).get("refunded").toString());s.auditRefund(admin,rid,true,m());s.processRefund(rid,false);assertEquals(5,stock());}
 @Test void unpaidAndSkippingFulfillmentAreRejected(){long oid=id(create().get("id"));assertThrows(BusinessException.class,()->s.orderAction(admin,oid,"accept",m()));s.pay(u,oid,true);assertThrows(BusinessException.class,()->s.orderAction(admin,oid,"status",m("status",5)));s.orderAction(admin,oid,"accept",m());s.orderAction(admin,oid,"status",m("status",3));s.orderAction(admin,oid,"status",m("status",4));s.orderAction(admin,oid,"status",m("status",5));assertEquals(5,id(s.order(oid,u).get("status")));}
 @Test void merchantRejectionCreatesRefund(){long oid=id(create().get("id"));s.pay(u,oid,true);assertThrows(BusinessException.class,()->s.orderAction(admin,oid,"reject",m()));s.orderAction(admin,oid,"reject",m("reason","花材不足"));var r=db.one("SELECT id FROM refund_record WHERE order_id=#{p.id}",m("id",oid));assertNotNull(r);s.processRefund(id(r.get("id")),false);assertEquals("99.90",s.order(oid,u).get("refunded").toString());assertEquals(5,stock());}
 @Test void paidMadeFlowersDoNotReturnToStockOnRefund(){long oid=id(create().get("id"));s.pay(u,oid,true);s.orderAction(admin,oid,"accept",m());s.orderAction(admin,oid,"status",m("status",3));long rid=id(((Map<?,?>)s.applyRefund(u,m("order_id",oid,"amount","99.90","reason","质量问题"))).get("id"));s.auditRefund(admin,rid,true,m());s.processRefund(rid,false);assertEquals(4,stock());}
 @Test void reviewRequiresOwnershipCompletionAndUniqueItem(){long oid=id(create().get("id")),item=id(((List<Map<String,Object>>)s.order(oid,u).get("items")).get(0).get("id"));var body=m("order_item_id",item,"rating",5,"content","鲜花很好");assertThrows(BusinessException.class,()->s.saveReview(u,null,body));s.pay(u,oid,true);s.orderAction(admin,oid,"accept",m());for(int next:new int[]{3,4,5})s.orderAction(admin,oid,"status",m("status",next));assertThrows(BusinessException.class,()->s.saveReview(v,null,body));long rid=id(((Map<?,?>)s.saveReview(u,null,body)).get("id"));assertThrows(Exception.class,()->s.saveReview(u,null,body));assertThrows(BusinessException.class,()->s.deleteReview(v,rid));assertThrows(BusinessException.class,()->s.moderate(admin,rid,m("status",0)));s.reply(admin,rid,m("content","谢谢喜欢"));}
 @Test void rbacOwnershipAndJwtTampering()throws Exception {long oid=id(create().get("id"));http.perform(get("/api/admin/orders").header("Authorization",bearer(u))).andExpect(status().isForbidden());http.perform(get("/api/order/"+oid).header("Authorization",bearer(v))).andExpect(status().isForbidden());http.perform(get("/api/order/list")).andExpect(status().isUnauthorized());String tampered=bearer(u);tampered=tampered.substring(0,tampered.length()-4)+"xxxx";http.perform(get("/api/order/list").header("Authorization",tampered)).andExpect(status().isUnauthorized());}
 @Test void disabledUserAndPasswordChangesInvalidateExistingTokens()throws Exception {String before=bearer(u);s.userStatus(admin,u,0);http.perform(get("/api/order/list").header("Authorization",before)).andExpect(status().isUnauthorized());s.userStatus(admin,u,1);String token=bearer(u);s.password(u,m("old_password","Pass123!","password","NewPass123!"));http.perform(get("/api/order/list").header("Authorization",token)).andExpect(status().isUnauthorized());}
 @Test void imageMagicContentAndOwnershipAreChecked()throws Exception {var fake=new MockMultipartFile("file","x.jpg","image/jpeg","<script>alert(1)</script>".getBytes());assertThrows(BusinessException.class,()->media.upload(u,"review",fake));var image=new BufferedImage(3,3,BufferedImage.TYPE_INT_RGB);var out=new ByteArrayOutputStream();ImageIO.write(image,"png",out);var result=(Map<?,?>)media.upload(u,"review",new MockMultipartFile("file","x.png","image/png",out.toByteArray()));String url=result.get("url").toString();s.ownImage(u,url,"review");assertThrows(BusinessException.class,()->s.ownImage(v,url,"review"));}
 @Test void searchTreatsInjectionAsText()throws Exception {var r=s.products(false,"' OR 1=1 --",0,1,12);assertEquals(0,id(r.get("total")));}
 @Test void revenueUsesOnlySuccessAndTrendWorksOnBothDatabases(){var before=(Map<?,?>)s.overview();var initial=new java.math.BigDecimal(before.get("net").toString());long oid=id(create().get("id"));s.pay(u,oid,false);assertEquals(0,new java.math.BigDecimal(((Map<?,?>)s.overview()).get("net").toString()).compareTo(initial));s.pay(u,oid,true);long rid=id(((Map<?,?>)s.applyRefund(u,m("order_id",oid,"amount","40.00","reason","部分退款"))).get("id"));s.auditRefund(admin,rid,true,m());s.processRefund(rid,false);var after=(Map<?,?>)s.overview();assertEquals(0,new java.math.BigDecimal(after.get("net").toString()).compareTo(initial.add(new java.math.BigDecimal("59.90"))));assertFalse(((List<?>)s.trend()).isEmpty());var revenue=(Map<?,?>)s.revenue("","",1,10);assertNotNull(revenue.get("totals"));}
 @Test void readEndpointsAndAdminPaginationWork()throws Exception {for(String path:List.of("/api/category/list","/api/product/list","/api/product/"+p,"/api/product/"+p+"/images","/api/flower-language/list","/api/flower-language/1","/api/review/product/"+p))http.perform(get(path)).andExpect(status().isOk());for(String path:List.of("products","stock/list","stock/records","stock/warning","orders","refunds","reviews","users","statistics/overview","statistics/trend","statistics/revenue","media","audit-logs"))http.perform(get("/api/admin/"+path).header("Authorization",bearer(admin))).andExpect(status().isOk());for(String path:List.of("cart/list","address/list","favorite/list","order/list","refund/my","review/my","ai/greeting/list"))http.perform(get("/api/"+path).header("Authorization",bearer(u))).andExpect(status().isOk());}
 @Test void templateModeIsExplicitAndRecordIsOwned(){assertThrows(BusinessException.class,()->ai.generate(u,m("scene","未知场景","receiver","同学","style","温柔浪漫")));var g=(Map<?,?>)ai.generate(u,m("scene","生日祝福","receiver","同学","style","文艺清新"));assertEquals("TEMPLATE",g.get("source"));assertTrue(g.get("content").toString().contains("同学"));assertEquals(u,id(db.one("SELECT user_id FROM greeting WHERE id=#{p.id}",m("id",g.get("id"))).get("user_id")));}
}
